import { expect, test, type Page } from '@playwright/test'

async function scrollToPageBottom(page: Page) {
  await page.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight))
}

async function navigateFromPrimaryNavigation(page: Page, linkName: string) {
  const header = page.locator('.header-shell')

  if ((page.viewportSize()?.width ?? Number.POSITIVE_INFINITY) < 640) {
    await header.getByRole('button', { name: '打开导航' }).click()
  }

  const navigation = header.locator('nav[aria-label="主导航"]:visible')
  await expect(navigation).toBeVisible()
  await navigation.getByRole('link', { name: linkName, exact: true }).click()
}

test('recent posts do not render article commit metadata', async ({ page }) => {
  await page.goto('/zh/')

  await expect(page.locator('.blog-sidebar-right a[href*="/commit/"]')).toHaveCount(0)
  await expect(page.locator('.blog-sidebar-right [data-content-tree]')).toBeVisible()
  await expect(page.locator('body')).not.toContainText('文件夹')
})

test('back to top returns the list to the top', async ({ page }) => {
  await page.goto('/zh/')
  await scrollToPageBottom(page)

  await page.getByRole('button', { name: /回到顶部/ }).click()
  await expect.poll(() => page.evaluate(() => window.scrollY)).toBeLessThanOrEqual(8)
})

test('home, category, and tag navigation never resolves to a blank route', async ({ page }) => {
  await page.goto('/zh/')

  await navigateFromPrimaryNavigation(page, '分类')
  await expect(page).toHaveURL('/zh/categories/')
  await expect(page.getByRole('heading', { level: 1, name: '全部分类' })).toBeVisible()

  await navigateFromPrimaryNavigation(page, '标签')
  await expect(page).toHaveURL('/zh/tags/')
  await expect(page.getByRole('heading', { level: 1, name: '全部标签' })).toBeVisible()

  await navigateFromPrimaryNavigation(page, '首页')
  await expect(page).toHaveURL('/zh/')
  await expect(page.locator('[data-post-shell]').first()).toBeVisible()
})

'use client'

import { useCallback, useEffect, useRef, useState } from 'react'
import { AnimatePresence, motion, useReducedMotion } from 'motion/react'
import Link from '@/components/Link'
import Icon from '@/components/Icon'
import { Skeleton } from '@/components/animata/Skeleton'
import { cardClass, mutedText } from '@/components/ui/styles'
import { type Locale, ui } from '@/lib/i18n'
import { animataEase, animataQuickDuration } from '@/components/animata/motion'

type SearchResult = {
  url: string
  excerpt: string
  meta: { title: string; image?: string }
}

type SearchState =
  | { phase: 'idle' }
  | { phase: 'loading'; query: string }
  | { phase: 'results'; query: string; results: SearchResult[] }
  | { phase: 'empty'; query: string }
  | { phase: 'error'; query: string }

type PagefindAPI = {
  init: () => void
  search: (q: string) => Promise<{ results: Array<{ data: () => Promise<SearchResult> }> }>
  debouncedSearch: (
    q: string,
    opts?: unknown,
    timeout?: number
  ) => Promise<{ results: Array<{ data: () => Promise<SearchResult> }> } | null>
  preload: (q: string) => void
  destroy: () => Promise<void>
}

const RESULT_LIMIT = 10

// Webpack intercepts `import("/pagefind/pagefind.js")` at build time and
// replaces it with a module-not-found error. Using `new Function` creates
// a runtime dynamic import that the bundler cannot statically analyse, so
// the browser's native import() runs at request time against the static
// asset generated by the pagefind CLI in out/pagefind/.
const loadPagefind = () =>
  new Function('return import("/pagefind/pagefind.js")')() as Promise<PagefindAPI>

export default function SearchPageClient({ locale }: { locale: Locale }) {
  const labels = ui[locale]
  const [query, setQuery] = useState('')
  const [state, setState] = useState<SearchState>({ phase: 'idle' })
  const shouldReduceMotion = useReducedMotion()
  const pagefindRef = useRef<PagefindAPI | null>(null)
  const pagefindLoadFailedRef = useRef(false)
  const activeSearchRef = useRef(0)
  const queryRef = useRef('')
  const inputRef = useRef<HTMLInputElement>(null)
  const headingId = 'search-page-heading'
  const statusId = 'search-status'

  useEffect(() => {
    inputRef.current?.focus()
  }, [])

  const performSearch = useCallback(async (searchQuery: string) => {
    const trimmedQuery = searchQuery.trim()
    const searchId = activeSearchRef.current + 1
    activeSearchRef.current = searchId

    if (!trimmedQuery) {
      setState({ phase: 'idle' })
      return
    }

    const pf = pagefindRef.current
    if (!pf) {
      setState(
        pagefindLoadFailedRef.current
          ? { phase: 'error', query: trimmedQuery }
          : { phase: 'loading', query: trimmedQuery }
      )
      return
    }

    setState({ phase: 'loading', query: trimmedQuery })

    try {
      const search = await pf.debouncedSearch(trimmedQuery, {}, 250)
      if (!search || activeSearchRef.current !== searchId) return

      const results = await Promise.all(search.results.slice(0, RESULT_LIMIT).map((r) => r.data()))

      if (activeSearchRef.current !== searchId) return

      if (results.length === 0) {
        setState({ phase: 'empty', query: trimmedQuery })
      } else {
        setState({ phase: 'results', query: trimmedQuery, results })
      }
    } catch {
      if (activeSearchRef.current === searchId) {
        setState({ phase: 'error', query: trimmedQuery })
      }
    }
  }, [])

  useEffect(() => {
    let cancelled = false

    loadPagefind()
      .then((pf) => {
        if (cancelled) {
          return
        }

        pf.init()
        pagefindRef.current = pf
        pagefindLoadFailedRef.current = false

        if (queryRef.current.trim()) {
          void performSearch(queryRef.current)
        }
      })
      .catch(() => {
        if (cancelled) return

        pagefindLoadFailedRef.current = true

        if (queryRef.current.trim()) {
          setState({ phase: 'error', query: queryRef.current.trim() })
        }
      })

    return () => {
      cancelled = true
      pagefindRef.current = null
    }
  }, [performSearch])

  const onInput = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const value = e.target.value
      setQuery(value)
      queryRef.current = value
      pagefindRef.current?.preload(value)
      void performSearch(value)
    },
    [performSearch]
  )

  const itemTransition = shouldReduceMotion
    ? { duration: 0 }
    : { duration: animataQuickDuration, ease: animataEase }
  let statusMessage: string = labels.searchHint

  if (state.phase === 'loading') {
    statusMessage = labels.searchLoading(state.query)
  } else if (state.phase === 'results') {
    statusMessage = labels.searchResultCount(state.results.length, state.query)
  } else if (state.phase === 'empty') {
    statusMessage = labels.searchNoResults(state.query)
  } else if (state.phase === 'error') {
    statusMessage = labels.searchUnavailable(state.query)
  }

  return (
    <div className="blog-shell mx-auto w-full px-4 pt-6 pb-12 sm:px-0 sm:pt-10">
      <h1
        id={headingId}
        className="mb-4 text-2xl leading-tight font-semibold tracking-tight text-slate-900 sm:mb-6 sm:text-4xl dark:text-white/90"
      >
        {labels.search}
      </h1>

      <section role="search" aria-labelledby={headingId}>
        <div
          className={`relative mb-3 ${cardClass} flex min-h-11 items-center gap-3 px-4 py-2.5 focus-within:ring-2 focus-within:ring-sky-500/30 motion-safe:transition-[box-shadow] motion-safe:duration-200 sm:mb-5 sm:px-5 sm:py-3`}
        >
          <Icon
            name="Search"
            className="h-5 w-5 shrink-0 text-slate-400 dark:text-white/40"
            inlineSpacing={false}
            decorative
          />
          <input
            ref={inputRef}
            type="search"
            value={query}
            onChange={onInput}
            aria-label={labels.search}
            className="w-full bg-transparent text-base text-slate-900 outline-none dark:text-white/90"
          />
        </div>
      </section>

      <div id={statusId} role="status" className="sr-only">
        {statusMessage}
      </div>

      <div
        data-search-results
        data-search-state={state.phase}
        aria-busy={state.phase === 'loading'}
        aria-describedby={statusId}
      >
        {state.phase === 'idle' && (
          <p className={`px-1 text-sm leading-6 ${mutedText}`}>{labels.searchHint}</p>
        )}

        {state.phase === 'loading' && (
          <div className="space-y-3">
            {[0, 1, 2].map((i) => (
              <div key={i} className={`${cardClass} px-4 py-3 sm:px-5 sm:py-4`}>
                <Skeleton className="mb-2 h-5 w-2/3" />
                <Skeleton className="h-4 w-full" />
              </div>
            ))}
          </div>
        )}

        {state.phase === 'empty' && (
          <p className={`px-1 text-sm leading-6 ${mutedText}`}>
            {labels.searchNoResults(state.query)}
          </p>
        )}

        {state.phase === 'error' && (
          <p className={`px-1 text-sm leading-6 ${mutedText}`}>
            {labels.searchUnavailable(state.query)}
          </p>
        )}

        {state.phase === 'results' && (
          <div className="space-y-3">
            <p className={`mb-2 px-1 text-sm ${mutedText}`}>
              {labels.searchResultCount(state.results.length, state.query)}
            </p>
            <AnimatePresence mode="popLayout">
              {state.results.map((result) => (
                <motion.div
                  key={result.url}
                  layout
                  initial={shouldReduceMotion ? false : { opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -8 }}
                  whileHover={shouldReduceMotion ? undefined : { y: -2 }}
                  transition={itemTransition}
                >
                  <Link
                    href={result.url}
                    data-blog-post-link
                    data-search-result-card
                    className={`${cardClass} block px-4 py-3 hover:ring-sky-300 motion-safe:transition-[box-shadow,color,background-color] motion-safe:duration-200 sm:px-5 sm:py-4 dark:hover:ring-sky-700`}
                  >
                    <h2 className="mb-1.5 text-base leading-6 font-medium [overflow-wrap:anywhere] text-slate-900 sm:text-lg dark:text-white/90">
                      {result.meta?.title || result.url}
                    </h2>
                    {result.excerpt && (
                      <p
                        className="text-sm leading-6 text-slate-600 dark:text-white/70 [&_mark]:rounded [&_mark]:bg-sky-100 [&_mark]:px-0.5 [&_mark]:text-sky-700 dark:[&_mark]:bg-sky-900/40 dark:[&_mark]:text-sky-300"
                        dangerouslySetInnerHTML={{ __html: result.excerpt }}
                      />
                    )}
                  </Link>
                </motion.div>
              ))}
            </AnimatePresence>
          </div>
        )}
      </div>
    </div>
  )
}

import SearchPageClient from '@/components/SearchPageClient'
import siteMetadata from '@/data/siteMetadata'
import { isLocale, locales, ui } from '@/lib/i18n'
import { localizedAlternates } from '@/lib/seo/alternates'
import { genPageMetadata } from 'app/seo'
import type { Metadata } from 'next'
import { notFound } from 'next/navigation'

export const generateStaticParams = async () => locales.map((locale) => ({ locale }))

export async function generateMetadata(props: {
  params: Promise<{ locale: string }>
}): Promise<Metadata> {
  const params = await props.params

  if (!isLocale(params.locale)) {
    return {}
  }

  return genPageMetadata({
    title: ui[params.locale].search,
    description: ui[params.locale].searchDescription,
    locale: params.locale,
    alternates: localizedAlternates(siteMetadata.siteUrl),
  })
}

export default async function Page(props: { params: Promise<{ locale: string }> }) {
  const params = await props.params

  if (!isLocale(params.locale)) {
    return notFound()
  }

  return <SearchPageClient locale={params.locale} />
}

import { Mail, Github, X, Telegram } from './icons'
import { ui, type Locale } from '@/lib/i18n'

const components = {
  mail: Mail,
  github: Github,
  x: X,
  telegram: Telegram,
}

const sizeClasses: Record<number, string> = {
  4: 'h-4 w-4',
  5: 'h-5 w-5',
  6: 'h-6 w-6',
  8: 'h-8 w-8',
  10: 'h-10 w-10',
