import { isLocale, locales } from '@/lib/i18n'

export function normalizePathname(pathname: string) {
  const normalized = pathname.startsWith('/') ? pathname : `/${pathname}`
  const withoutTrailingSlash = normalized.replace(/\/+$/, '')

  return withoutTrailingSlash || '/'
}

export function isHomePath(pathname: string) {
  const currentPath = normalizePathname(pathname)

  return currentPath === '/' || locales.some((locale) => currentPath === `/${locale}`)
}

export function isBlogPostPath(pathname: string) {
  const segments = normalizePathname(pathname).split('/').filter(Boolean)

  if (segments.length < 2 || !isLocale(segments[0])) {
    return false
  }

  return !['categories', 'tags', 'search'].includes(segments[1])
}

import { describe, expect, it } from 'vitest'
import { getSameDocumentFragmentId } from '@/lib/articleFragment'

const articleUrl = 'https://mizore.blog/zh/hardware/xiaomi-book-pro-14/?view=full'

describe('same-document article fragments', () => {
  it('decodes a fragment on the exact current document', () => {
    expect(getSameDocumentFragmentId('#%E9%97%AE%E9%A2%98%E4%B8%80', articleUrl)).toBe('问题一')
    expect(getSameDocumentFragmentId(`${articleUrl}#footnote-1`, articleUrl)).toBe('footnote-1')
  })

  it.each([
    'https://example.com/zh/hardware/xiaomi-book-pro-14/?view=full#heading',
    'https://mizore.blog/zh/another-post/?view=full#heading',
    'https://mizore.blog/zh/hardware/xiaomi-book-pro-14/?view=summary#heading',
    'https://mizore.blog/zh/hardware/xiaomi-book-pro-14/?view=full',
  ])('rejects a fragment outside the exact current document: %s', (href) => {
    expect(getSameDocumentFragmentId(href, articleUrl)).toBeNull()
  })

  it('rejects malformed fragment encoding without throwing', () => {
    expect(getSameDocumentFragmentId('#%E0%A4%A', articleUrl)).toBeNull()
  })
})

import { describe, expect, it } from 'vitest'
import { getPostImageUrls, toAbsoluteUrl } from '@/lib/postImages'

const siteUrl = 'https://mizore.blog'

describe('toAbsoluteUrl', () => {
  it('passes through http(s) urls unchanged', () => {
    expect(toAbsoluteUrl('https://example.com/x.png', siteUrl)).toBe('https://example.com/x.png')
  })

  it('resolves relative urls against the site url', () => {
    expect(toAbsoluteUrl('/static/images/a.png', siteUrl)).toBe(
      'https://mizore.blog/static/images/a.png'
    )
  })
})

describe('getPostImageUrls', () => {
  it('dedupes image and images entries', () => {
    const urls = getPostImageUrls({
      image: '/static/images/a.png',
      images: ['/static/images/a.png', '/static/images/b.png'],
      siteUrl,
    })
    expect(urls).toEqual([
      'https://mizore.blog/static/images/a.png',
      'https://mizore.blog/static/images/b.png',
    ])
  })

  it('falls back to the provided fallback when no images are present', () => {
    expect(
      getPostImageUrls({ image: null, images: undefined, fallback: '/static/banner.png', siteUrl })
    ).toEqual(['https://mizore.blog/static/banner.png'])
  })

  it('returns an empty array when nothing is available', () => {
    expect(getPostImageUrls({ siteUrl })).toEqual([])
  })

  it('keeps remote urls absolute', () => {
    expect(getPostImageUrls({ image: 'https://cdn.example.com/cover.png', siteUrl })).toEqual([
      'https://cdn.example.com/cover.png',
    ])
  })
})

import { describe, expect, it } from 'vitest'
import {
  getPostsByTerm,
  getTagCounts,
  getTermKeys,
  getTermSummaries,
  termSlug,
} from '@/lib/content/terms'

const posts = [
  { tags: ['Next.js', 'Blog'], categories: ['折腾'] },
  { tags: ['Next.js', 'Linux'], categories: ['折腾'] },
]

describe('term helpers', () => {
  it('preserves display labels while using slugs as route keys', () => {
    const summaries = getTagCounts(posts)

    expect(termSlug('Next.js')).toBe('nextjs')
    expect(summaries.nextjs).toEqual({ slug: 'nextjs', label: 'Next.js', count: 2 })
    expect(summaries.blog).toEqual({ slug: 'blog', label: 'Blog', count: 1 })
  })

  it('sorts summaries by count and then label', () => {
    expect(getTermSummaries(posts, 'tags').map((term) => term.label)).toEqual([
      'Next.js',
      'Blog',
      'Linux',
    ])
  })

  it('filters posts by route slug', () => {
    expect(getPostsByTerm(posts, 'tags', 'nextjs')).toHaveLength(2)
    expect(getTermKeys(getTagCounts(posts))).toEqual(['nextjs', 'blog', 'linux'])
  })
})

import { describe, expect, it } from 'vitest'
import { getRepoSourceFilePathCandidates } from '../../contentlayer/config/gitHistory'

describe('git history path candidates', () => {
  it('keeps the current topic path and the retired flat blog path', () => {
    expect(
      getRepoSourceFilePathCandidates('content/blog/zh/hardware/xiaomi-book-pro-14.md')
    ).toEqual([
      'content/blog/zh/hardware/xiaomi-book-pro-14.md',
      'content/blog/zh/xiaomi-book-pro-14.md',
      'data/blog/zh/hardware/xiaomi-book-pro-14.md',
      'data/blog/zh/xiaomi-book-pro-14.md',
    ])
  })

  it('does not invent a flat path for locale-root posts', () => {
    expect(getRepoSourceFilePathCandidates('content/blog/zh/xiaomi-book-pro-14.md')).toEqual([
      'content/blog/zh/xiaomi-book-pro-14.md',
      'data/blog/zh/xiaomi-book-pro-14.md',
    ])
  })
})

import { describe, expect, it } from 'vitest'
import { stripMarkdownSlugExtension } from '../../contentlayer/config/computedFields'

describe('blog slug hardening', () => {
  it('strips trailing markdown extensions from flattened path slugs', () => {
    expect(stripMarkdownSlugExtension('tech/use-grok-bot.md')).toBe('tech/use-grok-bot')
    expect(stripMarkdownSlugExtension('tech/use-grok-bot.md.md')).toBe('tech/use-grok-bot')
    expect(stripMarkdownSlugExtension('hardware/xiaomi-book-pro-14.mdx')).toBe(
      'hardware/xiaomi-book-pro-14'
    )
    expect(stripMarkdownSlugExtension('hardware/xiaomi-book-pro-14')).toBe(
      'hardware/xiaomi-book-pro-14'
    )
  })
})
